  if (archived) {
    // Disable editing as on an archived render, leaving range controls usable.
    for (const row of p.rows()) {
      for (const tag of ['input', 'button', 'select']) {
        for (const control of row.querySelectorAll(tag)) control.disabled = true;
      }
    }
  }
  return p;
}

