const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showAlert(message) {
  const alert = document.querySelector('#alert');
  alert.textContent = message;
  alert.hidden = !message;
}

function projectRow(project, refresh) {
  const row = document.createElement('div');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.textContent = 'Open project';
  open.addEventListener('click', () => {
    window.location.href = `/projects/${project.id}`;
  });
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const archive = document.createElement('button');
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    showAlert('');
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      refresh();
    } catch (error) { showAlert(error.message); }
    finally { archive.disabled = false; }
  });
  row.append(name, summary, open, archive);
  return row;
}

function renderRename(project) {
  const form = document.createElement('form');
  form.innerHTML = `
    <label for="new-project-name">New project name</label>
    <div class="create-controls">
      <input id="new-project-name" type="text" autocomplete="off">
      <button type="submit">Rename project</button>
    </div>`;
  const input = form.querySelector('input');
  const submit = form.querySelector('button');
  input.value = project.name;
  input.disabled = submit.disabled = Boolean(project.archived);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (submit.disabled) return;
    const name = input.value.trim();
    if (!name) { showAlert('Project name is required'); return; }
    showAlert('');
    submit.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      document.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      input.value = project.name;
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = Boolean(project.archived); }
  });
  app.append(form);
}

async function renderTasks(project) {
  const section = document.createElement('section');
  section.innerHTML = `
    <label for="default-task-priority" class="filter-label">Default task priority</label>
    <select id="default-task-priority">
      <option>Low</option><option>Normal</option><option>High</option>
    </select>
    <form id="task-form">
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <label for="task-filter" class="filter-label">Task filter</label>
    <select id="task-filter">
      <option>All</option><option>Open</option><option>Completed</option>
    </select>
    <label for="priority-filter" class="filter-label">Priority filter</label>
    <select id="priority-filter">
      <option>All</option><option>Low</option><option>Normal</option><option>High</option>
    </select>
    <section id="tasks" aria-label="Tasks"></section>`;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('#task-title');
  const submit = form.querySelector('button');
  const filter = section.querySelector('#task-filter');
  const priorityFilter = section.querySelector('#priority-filter');
  const list = section.querySelector('#tasks');
  const defaultPriority = section.querySelector('#default-task-priority');
  defaultPriority.value = project.default_priority;
  defaultPriority.disabled = Boolean(project.archived);
  defaultPriority.addEventListener('change', async () => {
    defaultPriority.disabled = true;
    showAlert('');
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_priority: defaultPriority.value }),
      });
      Object.assign(project, saved);
    } catch (error) { showAlert(error.message); }
    finally {
      defaultPriority.value = project.default_priority;
      defaultPriority.disabled = Boolean(project.archived);
    }
  });
  const path = `/api/projects/${project.id}/tasks`;
  let tasks = await api(path);

  function displayTasks() {
    const visible = tasks.filter(task =>
      (filter.value === 'All' ||
        (filter.value === 'Completed' ? task.completed : !task.completed)) &&
      (priorityFilter.value === 'All' || task.priority === priorityFilter.value));
    list.replaceChildren(...visible.map(task => {
      const row = document.createElement('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = Boolean(project.archived);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        showAlert('');
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showAlert(error.message);
        } finally { checkbox.disabled = false; }
      });
      const renameForm = document.createElement('form');
      renameForm.className = 'task-rename';
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.value = task.title;
      renameInput.disabled = Boolean(project.archived);
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameButton.disabled = Boolean(project.archived);
      renameForm.append(renameLabel, renameInput, renameButton);
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (renameButton.disabled) return;
        const newTitle = renameInput.value.trim();
        if (!newTitle) { showAlert('Task title is required'); return; }
        showAlert('');
        renameButton.disabled = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: newTitle }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) { showAlert(error.message); }
        finally { renameButton.disabled = Boolean(project.archived); }
      });
      const priorityLabel = document.createElement('label');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      priorityLabel.textContent = 'Task priority';
      const priority = document.createElement('select');
      priority.id = priorityLabel.htmlFor;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = option.textContent = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = Boolean(project.archived);
      priority.addEventListener('change', async () => {
        priority.disabled = true;
        showAlert('');
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) {
          priority.value = task.priority;
          showAlert(error.message);
        } finally { priority.disabled = Boolean(project.archived); }
      });
      const dueForm = document.createElement('form');
      const dueLabel = document.createElement('label');
      dueLabel.htmlFor = `task-due-date-${task.id}`;
      dueLabel.textContent = 'Task due date';
      const dueInput = document.createElement('input');
      dueInput.id = dueLabel.htmlFor;
      dueInput.type = 'text';
      dueInput.value = task.due_date || '';
      dueInput.disabled = Boolean(project.archived);
      const dueButton = document.createElement('button');
      dueButton.type = 'submit';
      dueButton.textContent = 'Save due date';
      dueButton.disabled = Boolean(project.archived);
      dueForm.append(dueLabel, dueInput, dueButton);
      dueForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (dueButton.disabled) return;
        showAlert('');
        dueButton.disabled = true;
        try {
          const saved = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueInput.value }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) { showAlert(error.message); }
        finally { dueButton.disabled = Boolean(project.archived); }
      });
      row.append(checkbox, title, renameForm, priorityLabel, priority, dueForm);
      return row;
    }));
  }
  displayTasks();
  filter.addEventListener('change', displayTasks);
  priorityFilter.addEventListener('change', displayTasks);
  submit.disabled = Boolean(project.archived);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (submit.disabled) return;
    const title = input.value.trim();
    if (!title) { showAlert('Task title is required'); return; }
    showAlert('');
    submit.disabled = true;
    try {
      const task = await api(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      displayTasks();
      input.value = '';
      input.focus();
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = false; }
  });
}

async function render() {
  const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.innerHTML = '<button id="back">Projects</button><h1></h1><p id="alert" role="alert" hidden></p>';
    document.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    try {
      const project = await api(`/api/projects/${match[1]}`);
      document.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      if (project.archived) {
        const notice = document.createElement('p');
        notice.textContent = 'Archived project';
        app.append(notice);
      }
      renderRename(project);
      await renderTasks(project);
    } catch (error) { showAlert(error.message); }
    return;
  }

  app.innerHTML = `
    <h1>Workboard</h1>
    <form>
      <label for="project-name">Project name</label>
      <div class="create-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    <p id="alert" role="alert" hidden></p>
    <label for="project-filter" class="filter-label">Project filter</label>
    <select id="project-filter"><option>Active</option><option>Archived</option></select>
    <section aria-label="Projects" id="projects"></section>`;
  const list = document.querySelector('#projects');
  const form = document.querySelector('form');
  const input = document.querySelector('#project-name');
  const submit = form.querySelector('button');
  const filter = document.querySelector('#project-filter');
  let projects = [];
  function displayProjects() {
    const archived = filter.value === 'Archived';
    list.replaceChildren(...projects.filter(project => Boolean(project.archived) === archived)
      .map(project => projectRow(project, displayProjects)));
  }
  filter.addEventListener('change', displayProjects);
  // Register creation only after loading existing projects to preserve row order.
  submit.disabled = true;
  try {
    projects = await api('/api/projects');
    displayProjects();
    submit.disabled = false;
  } catch (error) { showAlert(error.message); }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    const name = input.value.trim();
    if (!name) { showAlert('Project name is required'); return; }
    showAlert('');
    submit.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      displayProjects();
      input.value = '';
      input.focus();
    } catch (error) { showAlert(error.message); }
    finally { submit.disabled = false; }
  });
}

render();

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
// Migrate existing project databases without changing their IDs or tasks.
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
// Default existing and newly created tasks to Normal without changing task identity.
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
// Each project's default affects only tasks created after the selection is saved.
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
// Empty strings represent tasks without a due date, including pre-migration tasks.
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = db.prepare('SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const setTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setTaskDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');

function validDueDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function taskData(task) { return { ...task, completed: Boolean(task.completed) }; }
const projectSelect = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const getProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const archiveProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk.toString();
    if (body.length > 65536) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try { return JSON.parse(body); } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all());
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      if (!project) return json(response, 404, { error: 'Project not found' });
      const input = await readJson(request);
      if (input && Object.hasOwn(input, 'name')) {
        if (project.archived) return json(response, 403, { error: 'Archived project is read-only' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, project.id);
      } else if (input && Object.hasOwn(input, 'default_priority')) {
        if (project.archived) return json(response, 403, { error: 'Archived project is read-only' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, project.id);
      } else {
        if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archived must be a boolean' });
        archiveProject.run(Number(input.archived), project.id);
      }
      return json(response, 200, getProject.get(projectMatch[1]));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 403, { error: 'Archived project is read-only' });
      }
      if (!taskId && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskData));
      }
      if (!taskId && request.method === 'POST') {
        const input = await readJson(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title, project.default_priority);
        return json(response, 201, taskData(getTask.get(projectId, result.lastInsertRowid)));
      }
      if (taskId && request.method === 'PATCH') {
        if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          setTaskPriority.run(input.priority, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || (date !== '' && !validDueDate(date))) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setTaskDueDate.run(date, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completion must be a boolean' });
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return json(response, 200, taskData(getTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(response, 201, getProject.get(result.lastInsertRowid));
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'An unexpected error occurred' });
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';

// Small DOM stand-in lets the actual browser event handlers run without dependencies.
class Element {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.listeners = {};
    this.dataset = {};
    this.attributes = {};
    this.disabled = false;
    this.textContent = '';
  }
  focus() {}
  append(...children) { this.children.push(...children); }
  replaceChildren(...children) { this.children = children; }
  setAttribute(name, value) { this.attributes[name] = value; }
  get value() {
    return this.savedValue ?? (this.tag === 'select' ? this.children[0]?.value : '') ?? '';
  }
  set value(value) { this.savedValue = value; }
  set innerHTML(html) {
    this.children = [];
    const stack = [this];
    for (const token of html.match(/<[^>]+>|[^<]+/g) || []) {
      if (token.startsWith('</')) { stack.pop(); continue; }
      if (token.startsWith('<')) {
        const tag = token.match(/^<(\w+)/)[1];
        const child = new Element(tag);
        for (const match of token.matchAll(/([\w-]+)="([^"]*)"/g)) {
          child.setAttribute(match[1], match[2]);
          if (match[1] === 'id') child.id = match[2];
          if (match[1] === 'for') child.htmlFor = match[2];
        }
        child.disabled = /\sdisabled[\s>]/.test(token);
        stack.at(-1).append(child);
        if (tag !== 'input') stack.push(child);
      } else if (token.trim()) {
        stack.at(-1).textContent += token.trim();
        if (stack.at(-1).tag === 'option') stack.at(-1).value = token.trim();
      }
    }
  }
  querySelector(selector) { return this.querySelectorAll(selector)[0] || null; }
  querySelectorAll(selector) {
    const matches = [];
    for (const child of this.children) {
      if (selector.startsWith('#') ? child.id === selector.slice(1) : child.tag === selector) matches.push(child);
      matches.push(...child.querySelectorAll(selector));
    }
    return matches;
  }
  addEventListener(type, handler) { (this.listeners[type] ??= []).push(handler); }
  async fire(type) {
    assert.equal(this.disabled, false, 'control should be enabled');
    for (const handler of this.listeners[type] || []) await handler({ preventDefault() {} });
  }
}

async function page(archived = false) {
  const app = new Element('main');
  const alert = new Element('p');
  const tasks = [];
  for (const priority of ['Low', 'Normal', 'High']) {
    for (const completed of [false, true]) {
      tasks.push({ id: tasks.length + 1, project_id: 1, title: `${priority} ${completed ? 'done' : 'open'}`, priority, completed });
    }
  }
  const project = { id: 1, archived, default_priority: 'Normal' };
  const context = vm.createContext({
    document: {
      querySelector: selector => selector === '#app' ? app : alert,
      createElement: tag => new Element(tag),
    },
    fetch: async (path, options) => {
      if (!options) return { ok: true, json: async () => structuredClone(tasks) };
      const input = JSON.parse(options.body);
      if (path === '/api/projects/1') {
        Object.assign(project, input);
        return { ok: true, json: async () => structuredClone(project) };
      }
      if (options.method === 'POST') {
        const task = { id: tasks.length + 1, project_id: 1, title: input.title, completed: false, priority: project.default_priority };
        tasks.push(task);
        return { ok: true, json: async () => structuredClone(task) };
      }
      const task = tasks.find(task => path.endsWith(`/${task.id}`));
      Object.assign(task, input);
      return { ok: true, json: async () => structuredClone(task) };
    },
  });
  const source = await readFile(new URL('../public/app.js', import.meta.url), 'utf8');
  vm.runInContext(source.replace(/render\(\);\s*$/, ''), context);
  await context.renderTasks(structuredClone(project));
  const completion = app.querySelector('#task-filter');
  const priority = app.querySelector('#priority-filter');
  const rows = () => app.querySelector('#tasks').children;
  const titles = () => rows().map(row => row.querySelector('span').textContent);
  async function select(control, value) { control.value = value; await control.fire('change'); }
  return { app, alert, tasks, completion, priority, rows, titles, select };
}

test('all combinations intersect in creation order and do not change task data', async () => {
  const p = await page();
  assert.equal(p.completion.value, 'All');
  assert.equal(p.priority.value, 'All');
  assert.deepEqual(p.priority.children.map(option => option.textContent), ['All', 'Low', 'Normal', 'High']);
  const original = structuredClone(p.tasks);
  for (const completion of ['All', 'Open', 'Completed']) {
    await p.select(p.completion, completion);
    for (const priority of ['All', 'Low', 'Normal', 'High']) {
      await p.select(p.priority, priority);
      assert.equal(p.completion.value, completion);
      assert.deepEqual(p.titles(), p.tasks.filter(task =>
        (completion === 'All' || task.completed === (completion === 'Completed')) &&
        (priority === 'All' || task.priority === priority)).map(task => task.title));
    }
    assert.equal(p.priority.value, 'High');
  }
  assert.deepEqual(p.tasks, original);
});

test('priority, completion and rename edits retain filters and immediately update visible rows', async () => {
  const p = await page();
  await p.select(p.completion, 'Open');
  await p.select(p.priority, 'High');
  const rename = p.rows()[0].querySelector('form');
  rename.querySelector('input').value = '  Renamed high task  ';
  await rename.fire('submit');
  assert.deepEqual(p.titles(), ['Renamed high task']);
  assert.equal(p.rows()[0].querySelector('input').attributes['aria-label'], 'Complete Renamed high task');
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'High');
  await p.select(p.rows()[0].querySelector('select'), 'Low');
  assert.deepEqual(p.titles(), []);
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'High');
  await p.select(p.priority, 'Low');
  assert.deepEqual(p.titles(), ['Low open', 'Renamed high task']);
  const checkbox = p.rows()[1].querySelector('input');
  checkbox.checked = true;
  await checkbox.fire('change');
  assert.deepEqual(p.titles(), ['Low open']);
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'Low');
  await p.select(p.completion, 'Completed');
  assert.deepEqual(p.titles(), ['Low done', 'Renamed high task']);
  assert.deepEqual(p.tasks[4], { id: 5, project_id: 1, title: 'Renamed high task', priority: 'Low', completed: true });
  assert.equal(p.tasks.filter(task => task.completed).length, 4);
  const uncheck = p.rows()[1].querySelector('input');
  uncheck.checked = false;
  await uncheck.fire('change');
  assert.deepEqual(p.titles(), ['Low done']);
  assert.equal(p.completion.value, 'Completed');
  assert.equal(p.priority.value, 'Low');
});

test('archived project filters work while every task editing control stays disabled', async () => {
  const p = await page(true);
  await p.select(p.completion, 'Completed');
  await p.select(p.priority, 'Normal');
  assert.deepEqual(p.titles(), ['Normal done']);
  for (const tag of ['input', 'button', 'select']) {
    for (const control of p.rows()[0].querySelectorAll(tag)) assert.equal(control.disabled, true);
  }
  assert.equal(p.app.querySelector('#task-form').querySelector('button').disabled, true);
  assert.equal(p.priority.disabled, false);
  assert.equal(p.completion.disabled, false);
  const defaultPriority = p.app.querySelector('#default-task-priority');
  assert.equal(defaultPriority.value, 'Normal');
  assert.equal(defaultPriority.disabled, true);
});

test('changing the project default leaves filters and existing rows intact; new tasks inherit it', async () => {
  const p = await page();
  const control = p.app.querySelector('#default-task-priority');
  assert.deepEqual(control.children.map(option => option.textContent), ['Low', 'Normal', 'High']);
  assert.equal(control.value, 'Normal');
  await p.select(p.completion, 'Open');
  await p.select(p.priority, 'High');
  const existing = structuredClone(p.tasks);
  await p.select(control, 'Low');
  assert.equal(control.value, 'Low');
  assert.deepEqual(p.tasks, existing);
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'High');
  assert.deepEqual(p.titles(), ['High open']);
  p.app.querySelector('#task-title').value = 'Inherits Low';
  await p.app.querySelector('#task-form').fire('submit');
  assert.deepEqual(p.titles(), ['High open']);
  assert.equal(p.tasks.at(-1).priority, 'Low');
  await p.select(p.priority, 'Low');
  assert.deepEqual(p.titles(), ['Low open', 'Inherits Low']);
  await p.select(control, 'High');
  assert.deepEqual(p.titles(), ['Low open', 'Inherits Low']);
  assert.equal(p.tasks.at(-1).priority, 'Low');
});

test('due date controls save and clear independently without resetting filters or rename data', async () => {
  const p = await page();
  await p.select(p.completion, 'Open');
  await p.select(p.priority, 'High');
  function dueForm() { return p.rows()[0].querySelectorAll('form')[1]; }
  assert.equal(dueForm().querySelector('label').textContent, 'Task due date');
  assert.equal(dueForm().querySelector('button').textContent, 'Save due date');
  assert.equal(dueForm().querySelector('input').type, 'text');
  assert.equal(dueForm().querySelector('input').value, '');
  dueForm().querySelector('input').value = '2024-02-29';
  await dueForm().fire('submit');
  assert.equal(dueForm().querySelector('input').value, '2024-02-29');
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'High');
  assert.deepEqual(p.titles(), ['High open']);
  assert.equal(p.tasks[4].due_date, '2024-02-29');
  assert.equal(p.tasks[0].due_date, undefined);
  const rename = p.rows()[0].querySelector('form');
  rename.querySelector('input').value = 'New title';
  await rename.fire('submit');
  assert.equal(dueForm().querySelector('input').value, '2024-02-29');
  dueForm().querySelector('input').value = '';
  await dueForm().fire('submit');
  assert.equal(dueForm().querySelector('input').value, '');
  assert.deepEqual(p.titles(), ['New title']);
  assert.equal(p.completion.value, 'Open');
  assert.equal(p.priority.value, 'High');
});

